package io.github.testlens.migration.tooling;
import org.junit.jupiter.api.Test;import java.nio.charset.StandardCharsets;import java.util.List;import java.util.Set;import static org.junit.jupiter.api.Assertions.*;
class MigrationCheckpointJsonTest{
 @Test void deterministicRoundTripAndNoTimestampOrAbsolutePath(){var source=new MigrationSourceStateFingerprint(1,"migration-source-state-v1:sha256:"+"a".repeat(64),"b".repeat(40),List.of(new MigrationSourceStateFingerprint.FileState("src/A.java",Set.of("UNSTAGED"),null,new MigrationSourceStateFingerprint.WorktreeContent(MigrationSourceStateFingerprint.WorktreeState.REGULAR_FILE,"c".repeat(64),3,null))),3,MigrationSourceStateFingerprint.Completeness.COMPLETE,List.of());var p=new MigrationGitPreflight(MigrationGitPreflight.RepositoryStatus.DETECTED,"migration-repository-binding-v1:sha256:"+"d".repeat(64),"migration-worktree-binding-v1:sha256:"+"e".repeat(64),"git version 2.55.0","sha1",new MigrationGitPreflight.Head(MigrationGitPreflight.HeadState.NAMED_BRANCH,"f".repeat(40),"b".repeat(40),"main"),null,List.of(),List.of(new MigrationGitPreflight.StatusEntry("src/A.java",MigrationGitPreflight.ChangeKind.MODIFIED,".","M","100644","f".repeat(40))),List.of(),List.of(),List.of(),List.of(),List.of(),MigrationGitPreflight.SparseCheckout.DISABLED,new MigrationGitPreflight.SubmoduleSummary(false,MigrationGitPreflight.Completeness.COMPLETE,0,List.of()),MigrationGitPreflight.Completeness.COMPLETE,List.of());var c=MigrationCheckpoint.create(p,source,MigrationCheckpoint.Configuration.create(MigrationIsolationPlan.Choice.USE_CURRENT_WORKTREE,MigrationCheckpoint.IntendedMode.PREFLIGHT_ONLY,MigrationCheckpoint.StateStorage.EXTERNAL_TOOL_ROOT),List.of(),null,null);var codec=new MigrationCheckpointJson();byte[]one=codec.write(c),two=codec.write(c);assertArrayEquals(one,two);assertEquals(c,codec.read(one));String json=new String(one,StandardCharsets.UTF_8);assertFalse(json.contains("timestamp"));assertFalse(json.contains("C:\\"));}
 @Test void duplicateAndUnknownFieldsAreRejected(){var codec=new MigrationCheckpointJson();assertThrows(RuntimeException.class,()->codec.read("{\"schemaVersion\":1,\"schemaVersion\":1}".getBytes(StandardCharsets.UTF_8)));assertThrows(RuntimeException.class,()->codec.read("{\"unknown\":1}".getBytes(StandardCharsets.UTF_8)));}
}
